#nullable enable // autogenerated

using System;
using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Damages;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Callbacks;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaProjectileNames.hookshot)]
    public class Hookshot : EntityBehaviourDefinition
    {
        public Hookshot(string nsp, string name) : base(nsp, name)
        {
            AddTrigger(VanillaLevelCallbacks.POST_PROJECTILE_HIT, PostProjectileHitCallback);
            AddModifier(new BooleanModifier(VanillaProjectileProps.NO_HIT_ENTITIES, BooleanOperator.Or, PROP_NO_HIT_ENTITIES));
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.PlaySound(VanillaSoundID.hookshotFire);
            entity.Level.AddLoopSoundEntity(VanillaSoundID.hookshotLoop, entity.ID);
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            switch (entity.State)
            {
                case VanillaProjectileStates.IDLE:
                    UpdateIdleState(entity);
                    break;
                case VanillaProjectileStates.HOOKSHOT_CAUGHT:
                    UpdateCaughtState(entity);
                    break;
                case VanillaProjectileStates.HOOKSHOT_RETURNING:
                    UpdateReturningState(entity);
                    break;
            }
        }
        public override void PostContactGround(Entity entity, Vector3 velocity)
        {
            base.PostContactGround(entity, velocity);
            if (entity.State == VanillaProjectileStates.IDLE)
            {
                StartReturning(entity);
            }
        }
        public static bool IsValidTarget(Entity projectile, Entity target)
        {
            return true;
        }
        private static void UpdateIdleState(Entity projectile)
        {
            if (projectile.IsProjectileOutsideView())
            {
                StartReturning(projectile);
            }
        }
        #region ×¥È¡
        private static void UpdateCaughtState(Entity projectile)
        {
            var parent = projectile.Parent;
            var target = projectile.Target;
            if (parent.ExistsAndAlive() && target.ExistsAndAlive())
            {
                projectile.Position = target.GetCenter();
                projectile.Velocity = Vector3.zero;
                if (!CanBeDraggedToTile(target))
                {
                    if (WillBeDraggedInsteadOfDraggingOther(parent, target))
                    {
                        DragEnemy(projectile, parent, target);
                    }
                    else
                    {
                        DragEnemy(projectile, target, parent);
                    }
                }
                if (Mathf.Abs(parent.Position.x - target.Position.x) <= DRAG_ENEMY_RETURN_THRESOLD)
                {
                    StartReturning(projectile);
                    return;
                }
                var stateTimer = GetOrCreateStateTimerSeconds(projectile, CATCH_TIMEOUT_SECONDS);
                if (stateTimer.RunToExpired())
                {
                    StartReturning(projectile);
                }
            }
            else
            {
                StartReturning(projectile);
            }
        }
        public static bool CanCatch(Entity projectile)
        {
            return projectile.State == VanillaProjectileStates.IDLE;
        }
        public static bool IsCaught(Entity projectile)
        {
            return projectile.State == VanillaProjectileStates.HOOKSHOT_CAUGHT;
        }
        public static void Catch(Entity projectile, Entity target)
        {
            projectile.PlaySound(VanillaSoundID.hookshotTarget);
            projectile.Position = target.GetCenter();
            projectile.Target = target;
            projectile.State = VanillaProjectileStates.HOOKSHOT_CAUGHT;

            if (CanBeDraggedToTile(target))
            {
                DragToTile(projectile, target);
            }

            var stateTimer = GetStateTimer(projectile);
            if (stateTimer != null)
            {
                stateTimer.ResetSeconds(CATCH_TIMEOUT_SECONDS);
            }
        }
        #endregion

        #region ÍÏ×§
        public static bool CanBeDraggedToTile(Entity target)
        {
            return !target.IsStableContraption() && (target.Type == EntityTypes.PLANT || target.Type == EntityTypes.OBSTACLE);
        }
        public static bool WillBeDraggedInsteadOfDraggingOther(Entity self, Entity other)
        {
            if (other.Type == EntityTypes.PLANT || other.Type == EntityTypes.OBSTACLE)
            {
                if (other.IsStableContraption())
                {
                    return true;
                }
            }
            else if (other.Type == EntityTypes.BOSS)
            {
                return true;
            }
            else if (other.Type == EntityTypes.ENEMY)
            {
                return self.GetMass() < other.GetMass();
            }
            return false;
        }
        public static void DragToTile(Entity projectile, Entity target)
        {
            var direction = 1;
            if (projectile.Parent != null)
            {
                direction = Math.Sign(projectile.Parent.Position.x - target.Position.x);
                if (direction == 0)
                {
                    direction = 1;
                }
            }
            var column = target.GetColumn() + direction;
            var lane = target.GetLane();
            if (target.Level.ValidateGridOutOfBounds(column, lane))
            {
                target.StartChangingGrid(column, lane, speedFactor: DRAG_TO_TILE_SPEED_FACTOR);
            }
            else
            {
                var outOfBoundDamageEffects = new DamageEffectList(VanillaDamageEffects.OUT_OF_BOUND);
                target.Die(outOfBoundDamageEffects, projectile);
            }
        }
        public static void DragEnemy(Entity projectile, Entity dragTarget, Entity dragToWhere)
        {
            var direction = Mathf.Sign(dragToWhere.Position.x - dragTarget.Position.x);
            dragTarget.Position += Vector3.right * (direction * DRAG_ENEMY_SPEED);
        }
        #endregion

        #region ·µ»Ø
        private static void UpdateReturningState(Entity projectile)
        {
            var parent = projectile.Parent;
            if (!parent.ExistsAndAlive())
            {
                projectile.Remove();
                return;
            }
            var target = HookshotUserBuff.GetHookGunPoint(parent);
            var distance = target - projectile.Position;
            projectile.Velocity = distance.normalized * RETURN_SPEED;
            if (distance.sqrMagnitude <= SQR_RETURN_REMOVE_THRESOLD)
            {
                projectile.Remove();
            }
        }
        private static void StartReturning(Entity projectile)
        {
            projectile.State = VanillaProjectileStates.HOOKSHOT_RETURNING;
        }
        #endregion
        private void PostProjectileHitCallback(VanillaLevelCallbacks.PostProjectileHitParams args, CallbackResultVoid result)
        {
            var hit = args.hit;
            var projectile = hit.Projectile;
            var other = hit.Other;
            if (!projectile.HasBehaviour(this))
                return;
            if (!IsValidTarget(projectile, other))
                return;

            if (!CanCatch(projectile))
                return;
            Catch(projectile, other);
        }
        public static void SetStateTimer(Entity entity, FrameTimer value) => entity.SetProperty(PROP_STATE_TIMER, value);
        public static FrameTimer? GetStateTimer(Entity entity) => entity.GetProperty<FrameTimer>(PROP_STATE_TIMER);
        public static FrameTimer GetOrCreateStateTimerSeconds(Entity entity, float seconds) => entity.GetOrCreateTimerSeconds(PROP_STATE_TIMER, seconds);

        public const float DRAG_TO_TILE_SPEED_FACTOR = 0.2f;
        public const float DRAG_ENEMY_SPEED = 3f;
        public const float DRAG_ENEMY_RETURN_THRESOLD = DRAG_ENEMY_SPEED * 3f;
        public const float CATCH_TIMEOUT_SECONDS = 0.5f;
        public const float RETURN_SPEED = 10;
        public const float SQR_RETURN_SPEED = RETURN_SPEED * RETURN_SPEED;
        public const float SQR_RETURN_REMOVE_THRESOLD = SQR_RETURN_SPEED * 3;
        public static readonly PropertyMeta<FrameTimer> PROP_STATE_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("state_timer");
        public static readonly PropertyMeta<bool> PROP_NO_HIT_ENTITIES = new VanillaEntityPropertyMeta<bool>("no_hit_entities", false);
    }
}